if (!require("pacman")) install.packages("pacman")
pacman::p_load(dplyr, readr, tidyr)

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT <- .ROOT

events <- read_csv(file.path(PROJECT, "data/raw/scandal_departures_event_list.csv"),
                    show_col_types = FALSE)
depart <- read_csv(file.path(PROJECT, "data/processed/ministerial_departures_annual_1979_2025.csv"),
                    show_col_types = FALSE)

annual_events <- events |> count(year, name = "n_scandal")

annual <- tibble(year = 1979:2025) |>
  left_join(annual_events, by = "year") |>
  mutate(n_scandal = replace_na(n_scandal, 0)) |>
  left_join(depart |> select(year, n_active_ministers), by = "year") |>
  mutate(scandal_rate_pct = 100 * n_scandal / n_active_ministers)

write_csv(annual, file.path(PROJECT, "data/processed/scandal_resignations_annual_1979_2025.csv"))

cat(sprintf("Saved: %s\n", file.path(PROJECT, "data/processed/scandal_resignations_annual_1979_2025.csv")))
cat(sprintf("\nTotal financial-scandal events, 1979-2025: %d\n", sum(annual$n_scandal)))
cat("Years with an event:\n")
print(annual |> filter(n_scandal > 0) |> select(year, n_scandal, scandal_rate_pct))
cat(sprintf("\n1979-2007 (BDD-sourced, systematic): %d events\n",
            sum(annual$n_scandal[annual$year <= 2007])))
cat(sprintf("2008-2025 (this-session opportunistic search, lower bound): %d events\n",
            sum(annual$n_scandal[annual$year >= 2008])))
